// src/pages/Watchlist.jsx
import React, { useContext, useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import tmdbApi, { category } from '../api/tmdbApi';
import * as Config from "../constants/Config";
import apiConfig from '../api/apiConfig';
import './../scss/watchlist.scss';

const Watchlist = () => {
  const { currentUser } = useContext(AuthContext);
  const [activeTab, setActiveTab] = useState('want');
  const [recommendedMovies, setRecommendedMovies] = useState([]);
  const [loadingRecs, setLoadingRecs] = useState(false);

  const watchlist = currentUser?.watchlist || [];
  const watchedMovies = watchlist.filter(m => m && m.id && m.status === 'watched');

  const displayedMovies = watchlist.filter(
    m => m && m.id && m.status === activeTab
  );

useEffect(() => {
  let isMounted = true;

  const loadRecommendations = async () => {
    if (!currentUser || watchedMovies.length === 0) {
      if (isMounted) setRecommendedMovies([]);
      return;
    }

    setLoadingRecs(true);
    try {
      const res = await fetch(`${process.env.PUBLIC_URL || ''}/recommendations.json`);
      const jsonRecs = res.ok ? await res.json() : [];

      // Map SVD predictedRating by movieId for quick lookup
      const svdScoreMap = new Map();
      jsonRecs.forEach(item => {
        svdScoreMap.set(String(item.movieId), Number(item.predictedRating) || 0);
      });

      const excludedIds = new Set(watchlist.map(m => String(m.id)));

      // 1. Gather watched genres + fetch related movies for each watched movie
      const genreCounts = {};
      const relatedCandidates = new Map();

      await Promise.all(
        watchedMovies.map(async (w) => {
          // Fetch full details so we always have accurate TMDB genres
          try {
            const watchedDetail = await tmdbApi.detail(category.movie, w.id, { params: {} });
            (watchedDetail.genres || []).forEach((g) => {
              const gid = String(g.id);
              genreCounts[gid] = (genreCounts[gid] || 0) + 1;
            });
          } catch {}

          // Fetch similar movies from TMDB so niche genres (like Animation) are always represented
          try {
            const simRes = await tmdbApi.similar(category.movie, w.id, { params: { page: 1 } });
            (simRes?.results || []).slice(0, 12).forEach((m) => {
              const mid = String(m.id);
              if (!excludedIds.has(mid) && !relatedCandidates.has(mid)) {
                relatedCandidates.set(mid, m);
              }
            });
          } catch {}
        })
      );

      // 2. Also include top SVD candidates from recommendations.json
      const topSvdIds = jsonRecs
        .map(item => String(item.movieId))
        .filter(id => !excludedIds.has(id) && !relatedCandidates.has(id))
        .slice(0, 20);

      const svdDetails = await Promise.all(
        topSvdIds.map(async (id) => {
          try {
            return await tmdbApi.detail(category.movie, id, { params: {} });
          } catch {
            return null;
          }
        })
      );

      svdDetails.filter(Boolean).forEach((m) => {
        relatedCandidates.set(String(m.id), m);
      });

      // 3. Score every candidate: SVD predictedRating + strong genre match boost
      const scoredMovies = Array.from(relatedCandidates.values()).map((m) => {
        const movieGenreIds = m.genre_ids
          ? m.genre_ids.map(String)
          : (m.genres || []).map(g => String(g.id));

        const genreScore = movieGenreIds.reduce((sum, gid) => {
          return sum + (genreCounts[gid] || 0) * 1.2; // Strong boost for matching watched genres
        }, 0);

        const svdScore = svdScoreMap.get(String(m.id)) || 3.5;

        return {
          id: m.id,
          title: m.title || m.original_title || 'Unknown Title',
          poster: m.poster_path || m.backdrop_path || '',
          finalScore: svdScore + genreScore,
        };
      });

      const validMovies = scoredMovies
        .sort((a, b) => b.finalScore - a.finalScore)
        .slice(0, 12);

      if (isMounted) {
        setRecommendedMovies(validMovies);
      }
    } catch (err) {
      console.error('Error loading recommendations:', err);
      if (isMounted) setRecommendedMovies([]);
    } finally {
      if (isMounted) setLoadingRecs(false);
    }
  };

  loadRecommendations();
  return () => {
    isMounted = false;
  };
}, [currentUser, JSON.stringify(watchlist)]);

  if (!currentUser) {
    return (
      <div className="container" style={{ paddingTop: '150px', textAlign: 'center' }}>
        <h2>Please Sign In to view your Watchlist.</h2>
      </div>
    );
  }

  return (
    <div className="container watchlist-container">
      <h1>My Watchlist</h1>

      <div className="watchlist-tabs">
        <button 
          className={`tab-btn ${activeTab === 'want' ? 'active' : ''}`}
          onClick={() => setActiveTab('want')}
        >
          Want to Watch
        </button>
        <button 
          className={`tab-btn ${activeTab === 'watched' ? 'active' : ''}`}
          onClick={() => setActiveTab('watched')}
        >
          Watched
        </button>
      </div>

      <div className="watchlist-grid">
        {displayedMovies.length === 0 ? (
          <p style={{ color: '#888', fontSize: '1.2rem' }}>No movies in this list yet.</p>
        ) : (
          displayedMovies.map((movie, index) => (
            <Link 
              to={`/${Config.HOME_PAGE}/${category.movie}/${movie.id}`} 
              key={`${movie.id}-${index}`} 
              className="watchlist-card"
            >
              <img 
                src={movie.poster ? apiConfig.w500Image(movie.poster) : 'https://placehold.co/500x750/1f1f1f/ffffff?text=No+Image'} 
                alt={movie.title || 'Movie'} 
                onError={(e) => { 
                  e.target.onerror = null; 
                  e.target.src = 'https://placehold.co/500x750/1f1f1f/ffffff?text=No+Image'; 
                }}
              />
              <h3>{movie.title || 'Unknown Title'}</h3>
            </Link>
          ))
        )}
      </div>

      <div className="recommendations-section" style={{ marginTop: '3rem' }}>
        <h2>Recommended For You (Based on Watched)</h2>
        {watchedMovies.length === 0 ? (
          <p style={{ color: '#888', fontSize: '1rem' }}>
            Mark movies as Watched to get personalized recommendations.
          </p>
        ) : loadingRecs ? (
          <p style={{ color: '#888', fontSize: '1rem' }}>Loading recommendations...</p>
        ) : recommendedMovies.length === 0 ? (
          <p style={{ color: '#888', fontSize: '1rem' }}>No new recommendations available right now.</p>
        ) : (
          <div className="watchlist-grid">
            {recommendedMovies.map((movie) => (
              <Link
                to={`/${Config.HOME_PAGE}/${category.movie}/${movie.id}`}
                key={`rec-${movie.id}`}
                className="watchlist-card"
              >
                <img
                  src={movie.poster ? apiConfig.w500Image(movie.poster) : 'https://placehold.co/500x750/1f1f1f/ffffff?text=No+Image'}
                  alt={movie.title}
                  onError={(e) => {
                    e.target.onerror = null;
                    e.target.src = 'https://placehold.co/500x750/1f1f1f/ffffff?text=No+Image';
                  }}
                />
                <h3>{movie.title}</h3>
              </Link>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Watchlist;
